package upload;
import protocol.Signing;import java.nio.file.*;import java.util.*;import java.io.*;
/** On-disk chunk/object bytes; metadata intentionally process-local. */
public final class Sessions {
 private static final class Session {final int version,count;final long expires;final Map<Integer,String> hashes=new HashMap<>();boolean complete,linked;Session(int v,int n,long e){version=v;count=n;expires=e;}}
 private final Path root;private final String secret;private final Map<String,Session> sessions=new HashMap<>();private boolean cleanupPaused;
 public Sessions(Path root,String secret){this.root=root;this.secret=secret;try{Files.createDirectories(root);}catch(IOException e){throw new UncheckedIOException(e);}}
 public synchronized void start(String id,int version,int count,long expires,long now){if(!id.matches("[a-zA-Z0-9_-]+")||count<1||count>100||expires<=now||(version!=1&&version!=2))throw new IllegalArgumentException("session");if(sessions.containsKey(id))throw new IllegalStateException("exists");sessions.put(id,new Session(version,count,expires));}
 public synchronized void part(String id,int version,int index,byte[] bytes,int length,String hash,String signature,long now){Session s=Objects.requireNonNull(sessions.get(id));if(version!=s.version||now>=s.expires||s.complete||index<0||index>=s.count||length!=bytes.length||!Signing.hash(bytes).equals(hash)||!Signing.equal(Signing.sign(secret,version,id,index,hash),signature))throw new IllegalArgumentException("invalid fragment");String old=s.hashes.get(index);if(old!=null&&old.equals(hash))return;try{Files.write(root.resolve(id+"-"+index),bytes);s.hashes.put(index,hash);}catch(IOException e){throw new UncheckedIOException(e);}}
 public synchronized void complete(String id,String expected,long now){Session s=Objects.requireNonNull(sessions.get(id));if(s.complete)return;if(now>=s.expires||s.hashes.size()!=s.count)throw new IllegalStateException("incomplete/expired");try{var all=new ByteArrayOutputStream();for(int i=0;i<s.count;i++){byte[] b=Files.readAllBytes(root.resolve(id+"-"+i));if(!Signing.hash(b).equals(s.hashes.get(i)))throw new IllegalStateException("stored chunk tampered");all.write(b);}byte[] bytes=all.toByteArray();if(!Signing.hash(bytes).equals(expected))throw new IllegalStateException("whole hash");Files.write(root.resolve(id+".object"),bytes);s.complete=true;}catch(IOException e){throw new UncheckedIOException(e);}}
 public synchronized Path link(String id){Session s=Objects.requireNonNull(sessions.get(id));if(!s.complete)throw new IllegalStateException("unverified");s.linked=true;return root.resolve(id+".object");}
 public synchronized boolean visible(String id){return sessions.get(id).linked;}public synchronized void pauseCleanup(boolean b){cleanupPaused=b;}public synchronized void cleanup(long now){if(cleanupPaused)return;for(var e:sessions.entrySet()){Session s=e.getValue();if(now>=s.expires&&!s.complete){for(int i=0;i<s.count;i++)try{Files.deleteIfExists(root.resolve(e.getKey()+"-"+i));}catch(IOException ex){throw new UncheckedIOException(ex);}}}}
}